#include "cloudmoon_session.h"
#include <string.h>
#include <ctype.h>
static int b64_value(unsigned char c){if(c>='A'&&c<='Z')return c-'A';if(c>='a'&&c<='z')return c-'a'+26;if(c>='0'&&c<='9')return c-'0'+52;if(c=='+')return 62;if(c=='/')return 63;return -1;}
int cm_base64_decode(const char*in,uint8_t*out,size_t cap,size_t*outlen){size_t n,i,o=0;if(!in||!outlen)return -1;n=strlen(in);if((n&3)!=0)return -1;if(n/4>cap/3+1)return -1;for(i=0;i<n;i+=4){int a=b64_value((unsigned char)in[i]),b=b64_value((unsigned char)in[i+1]);int c=in[i+2]=='='?-2:b64_value((unsigned char)in[i+2]);int d=in[i+3]=='='?-2:b64_value((unsigned char)in[i+3]);uint32_t v;size_t add;if(a<0||b<0||c==-1||d==-1)return -1;if(c==-2&&d!=-2)return -1;if((c==-2||d==-2)&&i+4!=n)return -1;if(c==-2&&((b&15)!=0))return -1;if(d==-2&&c>=0&&((c&3)!=0))return -1;v=((uint32_t)a<<18)|((uint32_t)b<<12)|((uint32_t)(c<0?0:c)<<6)|(uint32_t)(d<0?0:d);add=c==-2?1:(d==-2?2:3);if(add>cap-o||(!out&&add))return -1;out[o++]=(uint8_t)(v>>16);if(add>1)out[o++]=(uint8_t)(v>>8);if(add>2)out[o++]=(uint8_t)v;}*outlen=o;return 0;}
int cm_cloudmoon_parse_https_url(const char*u,char*host,size_t hcap,uint16_t*port,char*path,size_t pcap){const char*a,*end,*colon,*path_start;size_t hn,pn;unsigned long pv=443;if(!u||!host||!hcap||!port||!path||!pcap||strncmp(u,"https://",8)!=0)return -1;a=u+8;end=a;while(*end&&*end!='/'&&*end!='?'&&*end!='#')end++;if(end==a||memchr(a,'@',(size_t)(end-a))||memchr(a,' ',(size_t)(end-a))||memchr(a,'[',(size_t)(end-a))||memchr(a,']',(size_t)(end-a)))return -1;colon=NULL;{const char*q;for(q=a;q<end;q++)if(*q==':')colon=q;}hn=(size_t)((colon?colon:end)-a);if(!hn||hn>=hcap)return -1;memcpy(host,a,hn);host[hn]=0;if(colon){const char*q=colon+1;if(q==end)return -1;pv=0;for(;q<end;q++){if(!isdigit((unsigned char)*q))return -1;pv=pv*10+(unsigned)(*q-'0');if(pv>65535)return -1;}if(pv==0)return -1;}path_start=end;if(*path_start=='#')return -1;if(*path_start=='?'){size_t qn=strlen(path_start);if(qn+1>=pcap)return -1;path[0]='/';memcpy(path+1,path_start,qn+1);pn=qn+1;}else if(*path_start=='/'){const char*q=path_start;while(*q&&*q!='#')q++;if(*q=='#')return -1;pn=(size_t)(q-path_start);if(pn>=pcap)return -1;memcpy(path,path_start,pn);path[pn]=0;}else{if(pcap<2)return -1;path[0]='/';path[1]=0;pn=1;}if(pn==0)return -1;*port=(uint16_t)pv;return 0;}
int cm_cloudmoon_get_coordinator(const char*encoded,char*host,size_t hcap,uint16_t*port,char*path,size_t pcap){uint8_t json[4096];size_t n;char url[1024];if(!encoded||cm_base64_decode(encoded,json,sizeof(json)-1,&n)!=0)return -1;json[n]=0;if(cm_json_get_string((const char*)json,n,"coorUrl",url,sizeof(url))<0)return -1;return cm_cloudmoon_parse_https_url(url,host,hcap,port,path,pcap);}
